function validateIco(buffer) {
  if (buffer.length < 22 || buffer.readUInt16LE(0) !== 0 || buffer.readUInt16LE(2) !== 1) throw new Error("Ungueltige ICO-Datei");
  const count = buffer.readUInt16LE(4);
  if (!count) throw new Error("Keine Bilder in der ICO-Datei");
  for (let i = 0; i < count; i++) {
    const offset = 6 + i * 16;
    const imageLength = buffer.readUInt32LE(offset + 8);
    const imageStart = buffer.readUInt32LE(offset + 12);
    if (imageStart + imageLength > buffer.length || buffer.subarray(imageStart, imageStart+8).toString("hex") !== "89504e470d0a1a0a") throw new Error("ICO-Bild ist kein gueltiges PNG");
    if (buffer[imageStart+25] !== 6) throw new Error("ICO-PNG ist nicht RGBA: Eintrag " + i);
  }
  return count;
}
try {
  if (!fs.existsSync(path.join(root, "package.json")) || !fs.existsSync(path.join(root,"app"))) throw new Error("Bitte im Projektordner C:\\Projekte\\rehkitzrettung ausfuehren.");
  const replacement = Buffer.from(iconData, "base64");
  const frames = validateIco(replacement);
  console.log("KORREKTES ICON: " + frames + " PNG-Bilder im RGBA-Format.");
  console.log("Zieldatei: " + target);
  if (check) {
    console.log("VORPRUEFUNG OK: keine Dateien veraendert.");
    process.exit(0);
  }
  if (!fs.existsSync(target)) throw new Error("app/favicon.ico ist nicht vorhanden; nichts ueberschrieben.");
  const backupDir = path.join(root, ".backups", "pwa-favicon-fix-" + new Date().toISOString().replace(/[:.]/g, "-"));
  fs.mkdirSync(backupDir, {recursive:true});
  fs.copyFileSync(target, path.join(backupDir, "favicon.ico"));
  fs.writeFileSync(target, replacement);
  const stored = fs.readFileSync(target);
  validateIco(stored);
  console.log("REPARATUR OK: app/favicon.ico korrigiert (RGBA).");
  console.log("BACKUP: " + path.join(backupDir, "favicon.ico"));
  console.log("Jetzt: npm run build");
} catch (error) {
  console.error("ABBRUCH: " + error.message);
  process.exitCode = 1;
}
